{
  "up": "Select molecule_chembl_id AS compound_chembl_id, canonical_smiles, compound_records.compound_key AS compound_key, docs.pubmed_id, docs.doi AS pubmed_id_or_doi, assays.description AS assay_description, activities.standard_type, activities.standard_relation, activities.standard_value, activities.standard_units, activities.activity_comment, target_dictionary.chembl_id AS target_chembl_id, target_dictionary.pref_name AS target_name, target_dictionary.organism AS target_organism From activities Join assays On activities.assay_id = assays.assay_id Join target_dictionary On assays.tid = target_dictionary.tid Join compound_records On activities.record_id = compound_records.record_id Join molecule_dictionary On compound_records.molregno = molecule_dictionary.molregno Join compound_structures On molecule_dictionary.molregno = compound_structures.molregno Where activities.bao_endpoint = 'BAO_0000190' And activities.standard_type = 'IC50' And activities.standard_relation = '=' And activities.standard_units = 'nM' And activities.standard_value IS NOT NULL And activities.standard_value > 0 And target_dictionary.pref_name = 'Phosphatidylinositol 4,5-bisphosphate 3‑kinase catalytic subunit alpha' And target_dictionary.tax_id = 9606 And (docs.pubmed_id IS NOT NULL Or docs.doi IS NOT NULL) And compound_structures.canonical_smiles IS NOT NULL Order By compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism"
}
